 const unsigned runtime=argc>1?unsigned(std::stoul(argv[1])):7;const int type=argc>2?std::stoi(argv[2]):5;const unsigned dedicated=argc>3?unsigned(std::stoul(argv[3])):1;
 Api hip(runtime);hip.Check(hip.hipInit(0),"hipInit");int count=0,version=0;hip.Check(hip.hipGetDeviceCount(&count),"count");hip.Check(hip.hipRuntimeGetVersion(&version),"version");printf("HIP runtime=%d devices=%d memory_type=%d flags=%u\n",version,count,type,dedicated);fflush(stdout);
