 auto info=d->GetResourceAllocationInfo(0,1,&rd);MemoryDesc md{};md.type=type;md.handle.win32.handle=sharedHandle;md.size=info.SizeInBytes;md.flags=dedicated;Handle imported=nullptr;int result=hip.hipImportExternalMemory(&imported,&md);printf("import_memory=%d %s allocation=%llu\n",result,hip.hipGetErrorName(result),info.SizeInBytes);fflush(stdout);hip.Check(result,"import memory");BufferDesc bd{};bd.size=bytes;void*mapped=nullptr;hip.Check(hip.hipExternalMemoryGetMappedBuffer(&mapped,imported,&bd),"map buffer");
 ID3D12Fence*fence=nullptr;ck(d->CreateFence(0,D3D12_FENCE_FLAG_SHARED,IID_PPV_ARGS(&fence)),"fence");HANDLE fenceHandle=nullptr;ck(d->CreateSharedHandle(fence,nullptr,GENERIC_ALL,nullptr,&fenceHandle),"fence handle");SemaphoreDesc sd{};sd.type=4;sd.handle.win32.handle=fenceHandle;Handle semaphore=nullptr;result=hip.hipImportExternalSemaphore(&semaphore,&sd);printf("import_fence=%d %s\n",result,hip.hipGetErrorName(result));fflush(stdout);hip.Check(result,"import fence");Handle stream=nullptr;hip.Check(hip.hipStreamCreate(&stream),"stream");
