 WaitParams wait{};wait.params.fence.value=1;hip.Check(hip.hipWaitExternalSemaphoresAsync(&semaphore,&wait,1,stream),"HIP wait 1");hip.Check(hip.hipStreamSynchronize(stream),"wait completion");std::vector<unsigned char>initial(bytes);hip.Check(hip.hipMemcpy(initial.data(),mapped,bytes,2),"HIP read shared");for(auto v:initial)if(v!=0x37)throw std::runtime_error("D3D12 -> HIP data mismatch");
